 *   { path: '/projects/{projectId}/tasks/{taskId}', component: 'TaskDetail' }
 * ]);
 *
 * console.log(routeConfigs);
 * // [
 * //   { path: '/users/:id', component: 'UserDetail', exact: true },
 * //   { path: '/users/:id/settings', component: 'UserSettings', exact: true },
 * //   { path: '/projects/:projectId/tasks/:taskId', component: 'TaskDetail', exact: true }
 * // ]
 * ```
 *
 * @example Next.js dynamic route generation
 * ```typescript
 * class NextJsRouteGenerator {
 *   generateFileStructure(openApiPaths: string[]) {
 *     return openApiPaths.map(path => {
 *       // Convert to Next.js file-based routing syntax
 *       const routerPath = toPathParams(path);
 *       const fileName = routerPath
 *         .replace(/:/g, '[') // :id becomes [id
 *         .replace(/\/\[([^\]]+)/g, '/[$1]') // [id becomes [id]
 *         .replace(/^\//,'') // Remove leading slash
 *         + '.tsx';
 *
 *       return {
 *         originalPath: path,
 *         routerPath,
 *         fileName
 *       };
 *     });
 *   }
 * }
 *
 * const generator = new NextJsRouteGenerator();
 * const structure = generator.generateFileStructure([
 *   '/users/{id}',
 *   '/posts/{slug}/comments/{commentId}'
 * ]);
 *
 * console.log(structure);
 * // [
 * //   {
 * //     originalPath: '/users/{id}',
 * //     routerPath: '/users/:id',
 * //     fileName: 'users/[id].tsx'
 * //   },
 * //   {
 * //     originalPath: '/posts/{slug}/comments/{commentId}',
 * //     routerPath: '/posts/:slug/comments/:commentId',
 * //     fileName: 'posts/[slug]/comments/[commentId].tsx'
 * //   }
 * // ]
 * ```
 *
 * @example Integration with path matching
 * ```typescript
 * import { matchPath } from 'react-router-dom';
 *
 * class PathMatcher {
 *   createMatcher(openApiPath: string) {
 *     const routerPath = toPathParams(openApiPath);
 *
 *     return (pathname: string) => {
 *       return matchPath(
 *         { path: routerPath, exact: true },
 *         pathname
