import type {
  EmptyEnrichments,
  OasOperation,
  OasOperationProjectionConstructorArgs,
  OasRef,
  OasSchema
} from '@skmtc/core'
import { ZodProjection } from '@skmtc/gen-zod'
import { TsClass, TsConstructor, TsMethod, toPathTemplate } from '@skmtc/lang-typescript'
import { TagClientBase } from './base.ts'
import { toMethodName, toTag } from './naming.ts'

/** Map a parameter schema to the TypeScript type of the method argument. */
const toParamType = (schema: OasSchema | OasRef<'schema'>): string => {
  const resolved = schema.isRef() ? schema.resolve() : schema

  switch (resolved.type) {
    case 'string':
      return 'string'
    case 'integer':
    case 'number':
      return 'number'
    case 'boolean':
      return 'boolean'
    default:
      return 'string'
  }
}

/**
 * One class per tag. The first operation of a tag constructs the whole
 * client: every operation sharing the tag becomes a method, so the class
 * and its file exist exactly once regardless of how many operations the
 * tag has (the entry's transform skips tags that already have a definition).
 */
export class TagClient extends TagClientBase {
  value: TsClass

  constructor(args: OasOperationProjectionConstructorArgs<EmptyEnrichments>) {
    super(args)

    this.value = new TsClass({
      classConstructor: new TsConstructor({ parameters: ['private baseUrl: string'] })
    })

    const { document } = this.context

    if (document.type !== 'oas') {
      throw new Error('@exp/gen-api-client only supports OpenAPI documents')
    }

    const tag = toTag(args.operation)

    document.value.operations
      .filter(operation => toTag(operation) === tag)
      .forEach(operation => this.value.addMethod(this.toMethod(operation)))
  }

  private toMethod(operation: OasOperation): TsMethod {
    const methodName = toMethodName(operation)

    const parameters = operation
      .toParams(['path'])
      .map(param => `${param.name}: ${toParamType(param.toSchema())}`)

    const bodySchema = operation.toRequestBody(({ schema }) => schema)

    if (bodySchema) {
      const bodyDefinition = this.insertNormalizedModel(ZodProjection, {
        schema: bodySchema,
        fallbackName: `${methodName}Body`
      })

      this.register({ imports: { zod: ['z'] } })

      parameters.push(`body: z.infer<typeof ${bodyDefinition.identifier.name}>`)
    }

    const url = '`${this.baseUrl}' + toPathTemplate(operation.path) + '`'

    const init = bodySchema
      ? `, { method: '${operation.method.toUpperCase()}', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }`
      : operation.method === 'get'
        ? ''
        : `, { method: '${operation.method.toUpperCase()}' }`

    const statements = [`const res = await fetch(${url}${init});`]

    const responseSchema = operation.toSuccessResponse()?.resolve().toSchema('application/json')

    if (responseSchema) {
      const responseDefinition = this.insertNormalizedModel(ZodProjection, {
        schema: responseSchema,
        fallbackName: `${methodName}Response`
      })

      statements.push(`return ${responseDefinition.identifier.name}.parse(await res.json());`)
    }

    return new TsMethod({
      name: methodName,
      async: true,
      parameters,
      body: statements.join('\n')
    })
  }

  override toString(): string {
    return `${this.value}`
  }
}

